// A tiny Kubernetes-like simulation: three nodes, three ReplicaSets, a scheduler.
// Pure reducer: random pod names are generated by the caller and passed in actions.

export type App = 'api' | 'web' | 'worker';
export type Status = 'Pending' | 'ContainerCreating' | 'Running' | 'Terminating';
export type Pod = { id: string; app: App; node: string | null; status: Status; since: number; createdAt: number };
export type ClusterNode = { name: string; cordoned: boolean };
export type ClusterEvent = {
  id: number;
  at: number;
  type: 'Normal' | 'Warning';
  reason: string;
  object: string;
  message: string;
};
export type State = { pods: Pod[]; nodes: ClusterNode[]; events: ClusterEvent[]; killed: number; seq: number };

export type Action =
  | { type: 'kill'; id: string; replacement: string; now: number }
  | { type: 'cordon'; name: string; now: number }
  | { type: 'uncordon'; name: string; now: number }
  | { type: 'drain'; name: string; replacements: string[]; now: number }
  | { type: 'tick'; now: number };

export const CAPACITY = 6;
const TERMINATION_MS = 900;
const SCHEDULING_MS = 450;
const STARTUP_MS = 1100;

export const APPS: Record<App, { replicaSet: string; replicas: number }> = {
  api: { replicaSet: 'api-7f9c4b', replicas: 4 },
  web: { replicaSet: 'web-5d8e21', replicas: 3 },
  worker: { replicaSet: 'worker-b3a6f0', replicas: 3 },
};
export const APP_NAMES = Object.keys(APPS) as App[];

// Same alphabet Kubernetes uses for generated name suffixes
const ALPHABET = 'bcdfghjklmnpqrstvwxz2456789';
export const suffix = (random: () => number) =>
  Array.from({ length: 5 }, () => ALPHABET[Math.floor(random() * ALPHABET.length)]).join('');

export const podName = (app: App, random: () => number = Math.random) => `${APPS[app].replicaSet}-${suffix(random)}`;

// Seeded so the server render and the first client render match
function seeded(seed: number) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function initialState(): State {
  const random = seeded(7);
  const nodes = ['node-a', 'node-b', 'node-c'].map((name) => ({ name, cordoned: false }));
  const pods: Pod[] = [];
  let index = 0;
  for (const app of APP_NAMES) {
    for (let r = 0; r < APPS[app].replicas; r++) {
      pods.push({
        id: podName(app, random),
        app,
        node: nodes[index++ % nodes.length].name,
        status: 'Running',
        since: 0,
        createdAt: 0,
      });
    }
  }
  return {
    pods,
    nodes,
    events: [{ id: 0, at: 0, type: 'Normal', reason: 'Ready', object: 'cluster/sdedu-lab', message: '3 nodes, 10 pods' }],
    killed: 0,
    seq: 1,
  };
}

function log(state: State, at: number, type: ClusterEvent['type'], reason: string, object: string, message: string): State {
  const event = { id: state.seq, at, type, reason, object, message };
  return { ...state, seq: state.seq + 1, events: [event, ...state.events].slice(0, 40) };
}

function terminate(state: State, id: string, replacement: string, now: number, reason: 'Killing' | 'Evicted') {
  const pod = state.pods.find((p) => p.id === id);
  if (!pod || pod.status === 'Terminating' || pod.status === 'Pending') return state;
  let next: State = {
    ...state,
    killed: state.killed + (reason === 'Killing' ? 1 : 0),
    pods: [
      ...state.pods.map((p) => (p.id === id ? { ...p, status: 'Terminating' as const, since: now } : p)),
      { id: replacement, app: pod.app, node: null, status: 'Pending', since: now, createdAt: now },
    ],
  };
  next = log(next, now, 'Normal', reason, `pod/${id}`, reason === 'Evicted' ? `evicted from ${pod.node}` : 'Stopping container');
  return log(next, now, 'Normal', 'SuccessfulCreate', `replicaset/${APPS[pod.app].replicaSet}`, `Created pod: ${replacement}`);
}

export const load = (pods: Pod[], node: string) => pods.filter((p) => p.node === node).length;

const setCordon = (state: State, name: string, cordoned: boolean) => ({
  ...state,
  nodes: state.nodes.map((n) => (n.name === name ? { ...n, cordoned } : n)),
});

export function reducer(state: State, action: Action): State {
  switch (action.type) {
    case 'kill':
      return terminate(state, action.id, action.replacement, action.now, 'Killing');

    case 'cordon':
      return log(setCordon(state, action.name, true), action.now, 'Normal', 'NodeNotSchedulable', `node/${action.name}`, 'cordoned');

    case 'uncordon':
      return log(setCordon(state, action.name, false), action.now, 'Normal', 'NodeSchedulable', `node/${action.name}`, 'uncordoned');

    case 'drain': {
      let next = log(setCordon(state, action.name, true), action.now, 'Normal', 'NodeNotSchedulable', `node/${action.name}`, 'draining');
      drainable(next, action.name).forEach((pod, i) => {
        next = terminate(next, pod.id, action.replacements[i], action.now, 'Evicted');
      });
      return next;
    }

    case 'tick': {
      const { now } = action;
      let next = state;

      const alive = next.pods.filter((p) => !(p.status === 'Terminating' && now - p.since > TERMINATION_MS));
      if (alive.length !== next.pods.length) next = { ...next, pods: alive };

      for (const pod of next.pods) {
        if (pod.status === 'ContainerCreating' && now - pod.since > STARTUP_MS) {
          next = {
            ...next,
            pods: next.pods.map((p) => (p.id === pod.id ? { ...p, status: 'Running' as const, since: now } : p)),
          };
          next = log(next, now, 'Normal', 'Started', `pod/${pod.id}`, 'Started container');
        }
      }

      // The scheduler binds one pending pod per tick to the least loaded node
      const pending = next.pods.find((p) => p.status === 'Pending' && now - p.since > SCHEDULING_MS);
      if (pending) {
        const target = next.nodes
          .filter((n) => !n.cordoned && load(next.pods, n.name) < CAPACITY)
          .sort((a, b) => load(next.pods, a.name) - load(next.pods, b.name))[0];
        if (target) {
          next = {
            ...next,
            pods: next.pods.map((p) =>
              p.id === pending.id ? { ...p, node: target.name, status: 'ContainerCreating' as const, since: now } : p,
            ),
          };
          next = log(next, now, 'Normal', 'Scheduled', `pod/${pending.id}`, `Assigned to ${target.name}`);
        } else if (next.events[0]?.reason !== 'FailedScheduling') {
          next = log(next, now, 'Warning', 'FailedScheduling', `pod/${pending.id}`, `0/${next.nodes.length} nodes are available`);
        }
      }
      return next;
    }
  }
}

/** Pods a drain would evict from a node (same selection the reducer uses). */
export const drainable = (state: State, node: string) =>
  state.pods.filter((p) => p.node === node && p.status !== 'Terminating');
